<?php declare(strict_types=1); namespace App\People\Infrastructure\Persistence\DBAL; use App\People\Domain\Enum\Gender; use App\People\Domain\Enum\MembershipStatus; use App\People\Domain\Model\Person; use App\People\Domain\ValueObject\EmailAddress; use App\People\Domain\ValueObject\PersonId; use App\People\Domain\ValueObject\PersonName; use App\People\Domain\ValueObject\PhoneNumber; use App\Shared\Domain\ValueObject\AuditTimestamps; final class PersonMapper {public function toDomain(array $r):Person{return Person::reconstitute(PersonId::fromString((string)$r['id']),PersonName::fromStrings((string)$r['first_name'],(string)$r['last_name']),$r['date_of_birth']?new \DateTimeImmutable((string)$r['date_of_birth']):null,Gender::from((string)$r['gender']),$r['email']?EmailAddress::fromString((string)$r['email']):null,$r['phone']?PhoneNumber::fromString((string)$r['phone']):null,MembershipStatus::from((string)$r['status']),new AuditTimestamps(new \DateTimeImmutable((string)$r['created_at']),new \DateTimeImmutable((string)$r['updated_at'])));} public function toRow(Person $p):array{return ['id'=>$p->id()->toString(),'first_name'=>$p->name()->firstName(),'last_name'=>$p->name()->lastName(),'date_of_birth'=>$p->dateOfBirth()?->format('Y-m-d'),'gender'=>$p->gender()->value,'email'=>$p->email()?->value(),'phone'=>$p->phone()?->value(),'status'=>$p->status()->value,'created_at'=>$p->createdAt()->format('Y-m-d H:i:s'),'updated_at'=>$p->updatedAt()->format('Y-m-d H:i:s')];}}
